// ╔══════════════════════════════════════════════════════════════════╗
// ║  EXTRACTOR DE IOCs — Wazuh → OpenCTI GraphQL                     ║
// ║  Aplana la alerta Wazuh, extrae MITRE/IPs/CVEs/dominios/hashes    ║
// ║  y construye una query GraphQL combinada para OpenCTI.            ║
// ╚══════════════════════════════════════════════════════════════════╝

// ─── 1. HELPER: aplanar objetos anidados ──────────────────────────
// { rule:{ mitre:{ id:["T1110","T1078"] }}} → { "rule.mitre.id[0]":"T1110", "rule.mitre.id[1]":"T1078" }
function flattenObject(obj, parentKey = '', result = {}) {
  for (const key in obj) {
    const newKey = parentKey ? `${parentKey}.${key}` : key;
    const val = obj[key];
    if (Array.isArray(val)) {
      val.forEach((item, i) => {
        if (item !== null && typeof item === 'object') {
          flattenObject(item, `${newKey}[${i}]`, result);
        } else {
          result[`${newKey}[${i}]`] = item;
        }
      });
    } else if (val !== null && typeof val === 'object') {
      flattenObject(val, newKey, result);
    } else {
      result[newKey] = val;
    }
  }
  return result;
}

// ─── 2. HELPER: validar IP pública enrutable ──────────────────────
const RE_IPV4       = /^(\d{1,3}\.){3}\d{1,3}$/;
const PRIVATE_IPV4  = /^(10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.|127\.|169\.254\.|0\.|255\.255\.255\.255$)/;
const PRIVATE_IPV6  = /^(::1$|fe80:|fc00:|fd00:)/i;

function isPublicIP(ip) {
  if (!ip || typeof ip !== 'string') return false;
  const t = ip.trim();
  if (RE_IPV4.test(t)) {
    // Valida rangos 0-255 en cada octeto
    if (!t.split('.').every(o => +o >= 0 && +o <= 255)) return false;
    return !PRIVATE_IPV4.test(t);
  }
  if (t.includes(':')) return !PRIVATE_IPV6.test(t);
  return false;
}

// ─── 3. ────────────────────────────────────────────
// Soporta múltiples formas de llegada: integración nativa Wazuh,
// copia cruda desde OpenSearch/Kibana, respuesta completa de search API, etc.
// El payload "Wazuh-core" siempre tiene .rule o .agent en la raíz.
function unwrapWazuh(raw) {
  const candidates = [
    raw,
    raw?.body,
    raw?._source,
    raw?.body?._source,
    Array.isArray(raw)        ? raw[0]           : null,
    Array.isArray(raw)        ? raw[0]?._source  : null,
    Array.isArray(raw?.body)  ? raw.body[0]      : null,
    Array.isArray(raw?.body)  ? raw.body[0]?._source : null,
    raw?.hits?.hits?.[0]?._source,        // respuesta completa de OpenSearch _search
    raw?.body?.hits?.hits?.[0]?._source
  ];
  for (const c of candidates) {
    if (c && typeof c === 'object' && (c.rule || c.agent)) return c;
  }
  return raw?.body || raw;   // fallback: devuelve algo aunque no haya rule/agent
}

const raw       = items[0].json;
const wazuhData = unwrapWazuh(raw);
const flat      = flattenObject(wazuhData);

// ─── 4. MITRE ATT&CK IDs ──────────────────────────────────────────
// Acepta tanto "rule.mitre.id" (string único) como "rule.mitre.id[0]" (array)
const mitreIds = [...new Set(
  Object.keys(flat)
    .filter(k => /^rule\.mitre\.id(\[\d+\])?$/.test(k))
    .map(k => flat[k])
    .filter(v => typeof v === 'string' && /^T\d{4}(\.\d{3})?$/.test(v))
)];

// ─── 5. IPs PÚBLICAS (alineado con wazuh_possible_fields.txt) ─────
const IP_FIELDS = [
  'data.srcip',                                                                     // Decoder genérico
  'data.dstip',                                                                     // Destino
  'data.audit.srcip',                                                               // Linux auditd
  'data.office365.ClientIP',                                                        // Microsoft 365
  'data.aws.source_ip_address',                                                     // AWS CloudTrail
  'data.aws.srcaddr',                                                               // AWS VPC Flow Logs
  'data.aws.dstaddr',                                                               // AWS VPC Flow Logs
  'data.aws.resource.instanceDetails.networkInterfaces.publicIp',                   // AWS GuardDuty
  'data.aws.service.action.networkConnectionAction.remoteIpDetails.ipAddressV4',    // AWS GuardDuty
  'data.port.remote_ip',                                                            // Syscollector
  'GeoLocation.ip'                                                                  // Enriquecimiento geoip
];

const ipsSet = new Set();
for (const field of IP_FIELDS) {
  if (isPublicIP(flat[field])) ipsSet.add(flat[field].trim());
}

// Fallback: extraer IPs del full_log si los campos estructurados no capturaron nada
const logText = [flat['full_log'], flat['previous_log'], flat['message']]
  .filter(Boolean).join(' ');
(logText.match(/\b(\d{1,3}\.){3}\d{1,3}\b/g) || [])
  .forEach(m => { if (isPublicIP(m)) ipsSet.add(m); });

const ips = [...ipsSet];

// ─── 6. CVEs ──────────────────────────────────────────────────────
const CVE_REGEX  = /CVE-\d{4}-\d{4,7}/gi;
const CVE_FIELDS = ['rule.cve', 'data.vulnerability.cve'];
const cvesSet    = new Set();

// Primero los campos dedicados (preferentes)
for (const field of CVE_FIELDS) {
  const v = flat[field];
  if (typeof v === 'string') {
    (v.match(CVE_REGEX) || []).forEach(c => cvesSet.add(c.toUpperCase()));
  }
}
// Luego barrido general (descripciones, títulos, etc.)
for (const key of Object.keys(flat)) {
  const v = String(flat[key] ?? '');
  (v.match(CVE_REGEX) || []).forEach(c => cvesSet.add(c.toUpperCase()));
}
const cves = [...cvesSet];

// ─── 7. DOMINIOS ──────────────────────────────────────────────────
const DOMAIN_FIELDS  = ['data.gcp.jsonPayload.queryName', 'data.url'];
const DOMAIN_REGEX   = /\b([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+)\b/gi;
const TLD_BLACKLIST  = /\.(arpa|local|lan|internal|localdomain)$/i;
const domainsSet     = new Set();

for (const field of DOMAIN_FIELDS) {
  const v = flat[field];
  if (typeof v !== 'string') continue;
  let candidate = v;
  try { candidate = new URL(v).hostname; } catch (_) { /* no es URL */ }
  for (const d of (candidate.match(DOMAIN_REGEX) || [])) {
    const dom = d.toLowerCase();
    if (RE_IPV4.test(dom))        continue;   // descarta IPs
    if (TLD_BLACKLIST.test(dom))  continue;   // descarta internos
    if (!dom.includes('.'))       continue;
    domainsSet.add(dom);
  }
}
const domains = [...domainsSet];

// ─── 8. HASHES ────────────────────────────────────────────────────
const RE_SHA256 = /^[a-f0-9]{64}$/i;
const RE_SHA1   = /^[a-f0-9]{40}$/i;
const RE_MD5    = /^[a-f0-9]{32}$/i;

const hashes = { sha256: new Set(), sha1: new Set(), md5: new Set() };
const check  = (re, bucket, v) => { if (v && re.test(v)) bucket.add(v.toLowerCase()); };

check(RE_SHA256, hashes.sha256, flat['syscheck.sha256_after']);
check(RE_SHA1,   hashes.sha1,   flat['syscheck.sha1_after']);
check(RE_SHA1,   hashes.sha1,   flat['data.virustotal.sha1']);
check(RE_SHA1,   hashes.sha1,   flat['data.virustotal.source.sha1']);
check(RE_MD5,    hashes.md5,    flat['syscheck.md5_after']);
check(RE_MD5,    hashes.md5,    flat['data.virustotal.source.md5']);

const hashesOut = {
  sha256: [...hashes.sha256],
  sha1:   [...hashes.sha1],
  md5:    [...hashes.md5]
};

// ─── 9. QUERY GRAPHQL PARA OPENCTI ────────────────────────────────
// Escape seguro: evita que un valor con comillas rompa la query
const gql = arr => arr.map(v => `"${String(v).replace(/"/g, '\\"')}"`).join(',');
const gqlStr = v => String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
const blocks = [];

if (mitreIds.length) {
  blocks.push(`
    techniques: attackPatterns(
      first: 50,
      filters: { mode: and, filters: [{ key: ["x_mitre_id"], values: [${gql(mitreIds)}] }], filterGroups: [] }
    ) {
      edges { node { id name description x_mitre_id
        killChainPhases { phase_name }
        stixCoreRelationships(relationship_type: "mitigates", first: 20) {
          edges { node { from { ... on CourseOfAction { name description } } } }
        }
      } }
    }`);
}

// ── IPs: dual (Indicators + Observables) ─────────────────────────
if (ips.length) {
  const searchIPs = gqlStr(ips.join(' '));  // OR implícito en search
  blocks.push(`
    ipIndicators: indicators(
      search: "${searchIPs}",
      first: 50
    ) {
      edges { node {
        id name pattern confidence revoked valid_from valid_until
        x_opencti_score x_opencti_main_observable_type
        objectLabel { value color }
        createdBy { ... on Identity { name } }
        stixCoreRelationships(relationship_type: "indicates", first: 20) {
          edges { node {
            confidence description
            to {
              ... on Malware       { id name description is_family malware_types }
              ... on ThreatActor   { id name description threat_actor_types }
              ... on Campaign      { id name description }
              ... on IntrusionSet  { id name description }
              ... on AttackPattern { id name x_mitre_id }
              ... on Tool          { id name }
            }
          } }
        }
      } }
    }
    ipObservables: stixCyberObservables(
      search: "${searchIPs}",
      types: ["IPv4-Addr","IPv6-Addr"],
      first: 50
    ) {
      edges { node {
        id observable_value
        ... on IPv4Addr { value }
        ... on IPv6Addr { value }
      } }
    }`);
}

if (cves.length) {
  blocks.push(`
    vulnerabilities: vulnerabilities(
      first: 50,
      filters: { mode: and, filters: [{ key: ["name"], values: [${gql(cves)}] }], filterGroups: [] }
    ) { edges { node { id name description x_opencti_cvss_base_score } } }`);
}

if (domains.length) {
  const searchDoms = gqlStr(domains.join(' '));
  blocks.push(`
    domainIndicators: indicators(
      search: "${searchDoms}",
      first: 50
    ) {
      edges { node {
        id name pattern confidence x_opencti_score revoked valid_until
        objectLabel { value }
        stixCoreRelationships(relationship_type: "indicates", first: 20) {
          edges { node { to {
            ... on Malware      { name description is_family }
            ... on ThreatActor  { name description }
            ... on Campaign     { name }
            ... on IntrusionSet { name }
          } } }
        }
      } }
    }
    domainObservables: stixCyberObservables(
      search: "${searchDoms}",
      types: ["Domain-Name","Hostname"],
      first: 20
    ) {
      edges { node {
        id observable_value
        ... on DomainName { value }
      } }
    }`);
}

// ── Hashes: dual ─────────────────────────────────────────────────
const allHashes = [...hashesOut.sha256, ...hashesOut.sha1, ...hashesOut.md5];
if (allHashes.length) {
  const searchH = gqlStr(allHashes.join(' '));
  blocks.push(`
    hashIndicators: indicators(
      search: "${searchH}",
      first: 50
    ) {
      edges { node {
        id name pattern confidence x_opencti_score
        objectLabel { value }
        stixCoreRelationships(relationship_type: "indicates", first: 20) {
          edges { node { to {
            ... on Malware      { name description is_family }
            ... on ThreatActor  { name }
            ... on Campaign     { name }
            ... on IntrusionSet { name }
          } } }
        }
      } }
    }
    fileObservables: stixCyberObservables(
      search: "${searchH}",
      types: ["StixFile"],
      first: 20
    ) {
      edges { node {
        ... on StixFile { id name hashes { algorithm hash } }
      } }
    }`);
}

// ─── 10. SALIDA ───────────────────────────────────────────────────
const iocs_extracted = {
  mitre_ids: mitreIds,
  ips, cves, domains,
  hashes: hashesOut
};

if (blocks.length === 0) {
  return [{ json: { skip: true, wazuhData, iocs_extracted } }];
}

const query = `query GetThreatContext {\n${blocks.join('\n')}\n}`;
return [{ json: { query, skip: false, wazuhData, iocs_extracted } }];

// ╔══════════════════════════════════════════════════════════════════╗
// ║  CLASIFICADOR v3 — Sin Merge, usando referencias cruzadas n8n     ║
// ╚══════════════════════════════════════════════════════════════════╝

// ─── 1. HELPERS ───────────────────────────────────────────────────
const nodeNames = edges => (edges || [])
  .map(e => e?.node?.from?.name || e?.node?.to?.name || e?.node?.name)
  .filter(Boolean);

function normalizeIndicator(ind) {
  if (!ind) return null;
  const threats = (ind.stixCoreRelationships?.edges || [])
    .map(rel => {
      const to = rel?.node?.to;
      if (!to?.name) return null;
      let type = 'Unknown';
      if ('is_family' in to)               type = 'Malware';
      else if ('threat_actor_types' in to) type = 'ThreatActor';
      else if ('x_mitre_id' in to)         type = 'AttackPattern';
      else if (to.name)                    type = 'Threat';
      return { type, name: to.name, description: to.description || null, is_family: to.is_family ?? null };
    })
    .filter(Boolean);
  return {
    name: ind.name || null,
    pattern: ind.pattern || null,
    confidence: ind.confidence ?? null,
    score: ind.x_opencti_score ?? null,
    revoked: ind.revoked ?? false,
    valid_until: ind.valid_until || null,
    labels: (ind.objectLabel || []).map(l => l.value).filter(Boolean),
    threats
  };
}

// ─── 2. REFERENCIAS DIRECTAS (no Merge) ───────────────────────────
// El Extractor siempre deja el Wazuh desenvuelto en wazuhData
const incident = $('Code in JavaScript').item.json.wazuhData || {};

// OpenCTI solo existe si la rama true del If se ejecutó
let ocData = null;
try {
  const oc = $('OpenCTI HTTP Request').item.json;
  // Busca .data tanto en raíz como en body (depende de config HTTP node)
  ocData = oc?.data || oc?.body?.data || null;
} catch (e) {
  // El nodo OpenCTI no se ejecutó (rama skip del If) — es normal
  ocData = null;
}

const hasEnrichment = !!ocData && Object.keys(ocData).length > 0;

// ─── 3. NORMALIZACIÓN (igual que antes) ───────────────────────────
const techniques = (ocData?.techniques?.edges || []).map(e => ({
  mitre_id: e.node.x_mitre_id || null,
  name: e.node.name,
  description: (e.node.description || '').substring(0, 500),
  kill_chain: [...new Set((e.node.killChainPhases || []).map(p => p.phase_name))],
  mitigations: nodeNames(e.node.stixCoreRelationships?.edges)
}));

const ipIndicators      = (ocData?.ipIndicators?.edges      || []).map(e => normalizeIndicator(e.node)).filter(Boolean);
const ipObservables     = (ocData?.ipObservables?.edges     || []).map(e => ({ id: e.node.id, value: e.node.value || e.node.observable_value }));
const cves              = (ocData?.vulnerabilities?.edges   || []).map(e => ({ name: e.node.name, cvss_base: e.node.x_opencti_cvss_base_score ?? null, description: (e.node.description || '').substring(0, 300) }));
const domainIndicators  = (ocData?.domainIndicators?.edges  || []).map(e => normalizeIndicator(e.node)).filter(Boolean);
const domainObservables = (ocData?.domainObservables?.edges || []).map(e => ({ id: e.node.id, value: e.node.value || e.node.observable_value }));
const hashIndicators    = (ocData?.hashIndicators?.edges    || []).map(e => normalizeIndicator(e.node)).filter(Boolean);
const fileObservables   = (ocData?.fileObservables?.edges   || []).map(e => ({ id: e.node.id, name: e.node.name, hashes: (e.node.hashes || []).map(h => `${h.algorithm}:${h.hash}`) }));

// ─── 4. THREATS ACTIVOS VS REVOCADOS ──────────────────────────────
const activeThreats  = arr => arr.some(i => !i.revoked && i.threats.length > 0);
const revokedThreats = arr => arr.some(i =>  i.revoked && i.threats.length > 0);

const has_threats = activeThreats(ipIndicators) || activeThreats(domainIndicators) || activeThreats(hashIndicators) || cves.length > 0;
const has_revoked_threats = revokedThreats(ipIndicators) || revokedThreats(domainIndicators) || revokedThreats(hashIndicators);

const activeSet  = new Set();
const revokedSet = new Set();
for (const arr of [ipIndicators, domainIndicators, hashIndicators]) {
  for (const ind of arr) {
    for (const t of ind.threats) {
      (ind.revoked ? revokedSet : activeSet).add(`${t.type}:${t.name}`);
    }
  }
}

// ─── 5. OUTPUT ────────────────────────────────────────────────────
return [{
  json: {
    incident,
    status: hasEnrichment ? 'Enriquecimiento completado' : 'Sin datos OpenCTI (skip o vacío)',
    has_threats,
    has_revoked_threats,
    confirmed_threats: [...activeSet],
    revoked_threats:   [...revokedSet],
    summary: {
      total_techniques:          techniques.length,
      total_ip_indicators:       ipIndicators.length,
      total_ip_observables:      ipObservables.length,
      total_cves:                cves.length,
      total_domain_indicators:   domainIndicators.length,
      total_domain_observables:  domainObservables.length,
      total_hash_indicators:     hashIndicators.length,
      total_file_observables:    fileObservables.length
    },
    threat_context: {
      techniques,
      ips:     { indicators: ipIndicators,     observables: ipObservables     },
      cves,
      domains: { indicators: domainIndicators, observables: domainObservables },
      files:   { indicators: hashIndicators,   observables: fileObservables   }
    },
    _debug: {
      incident_found: !!incident.rule,
      opencti_found:  hasEnrichment,
      opencti_keys:   ocData ? Object.keys(ocData) : []
    }
  }
}];

// ╔══════════════════════════════════════════════════════════════════╗
// ║  PARSER LLM + FUSOR v3 — Category-agnostic                        ║
// ║  Parsea la salida de Ollama, valida, y fusiona todo el contexto   ║
// ║  (Wazuh + OpenCTI + IA) en un objeto plano listo para             ║
// ║  Discord/OPNsense/futuras integraciones.                          ║
// ║                                                                   ║
// ║  Defensas:                                                        ║
// ║   - Parseo tolerante a markdown/texto extra                       ║
// ║   - Validación de enums (accion/gravedad)                         ║
// ║   - Fallback defensivo a 'analista' ante cualquier fallo          ║
// ║   - IOC Guard: 'bloquear' solo si IOC es actionable               ║
// ║   - Adaptación de opciones/previews/links al tipo de IOC          ║
// ║   - Soporte de subtécnicas MITRE (T1078.001)                      ║
// ║   - URLs con paréntesis escapados para Discord                    ║
// ╚══════════════════════════════════════════════════════════════════╝

// ─── 1. EXTRAER TEXTO DEL LLM ─────────────────────────────────────
const llmRaw = items[0]?.json || {};
let rawText = llmRaw.message?.content
           || llmRaw.response
           || llmRaw.text
           || llmRaw.content
           || '';

rawText = String(rawText)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// ─── 2. PARSEO DEFENSIVO ──────────────────────────────────────────
const FALLBACK = {
  _razonamiento: 'LLM_PARSE_ERROR',
  resumen: 'Error de parseo en la respuesta del LLM — revisión manual',
  gravedad: 'alta',
  accion: 'analista',
  motivo: 'Fallback defensivo: el modelo no devolvió JSON válido. Requiere supervisión humana.',
  ioc: 'Ninguno',
  mitigaciones: ['Revisar logs del nodo Ollama', 'Verificar prompt', 'Escalar si es repetitivo']
};

let ia = FALLBACK;
let parse_ok = false;
try {
  ia = JSON.parse(rawText);
  parse_ok = true;
} catch (e1) {
  const m = rawText.match(/\{[\s\S]*\}/);
  if (m) {
    try {
      ia = JSON.parse(m[0]);
      parse_ok = true;
    } catch (e2) {
      ia = { ...FALLBACK, motivo: `${FALLBACK.motivo} | Raw: ${rawText.substring(0, 200)}` };
    }
  } else {
    ia = { ...FALLBACK, motivo: `${FALLBACK.motivo} | Raw: ${rawText.substring(0, 200)}` };
  }
}

// ─── 3. VALIDACIÓN DE ENUMS ───────────────────────────────────────
const ACCIONES   = ['bloquear', 'analista', 'ignorar', 'escalar'];
const GRAVEDADES = ['baja', 'media', 'alta', 'critica'];

if (!ACCIONES.includes(ia.accion))     ia.accion   = 'analista';
if (!GRAVEDADES.includes(ia.gravedad)) ia.gravedad = 'media';

ia.resumen       = ia.resumen       || 'Sin resumen generado';
ia.motivo        = ia.motivo        || 'Sin motivo generado';
ia.ioc           = ia.ioc           || 'Ninguno';
ia._razonamiento = ia._razonamiento || 'N/A';
ia.mitigaciones  = Array.isArray(ia.mitigaciones) ? ia.mitigaciones : [];

// ─── 4. IOC GUARD (category-agnostic) ─────────────────────────────
const _RE_IPV4    = /^(\d{1,3}\.){3}\d{1,3}$/;
const _PRIVATE_RE = /^(10\.|172\.(1[6-9]|2\d|3[01])\.|192\.168\.|127\.|169\.254\.)/;
const _RE_SHA256  = /^[a-f0-9]{64}$/i;
const _RE_SHA1    = /^[a-f0-9]{40}$/i;
const _RE_MD5     = /^[a-f0-9]{32}$/i;
const _RE_DOMAIN  = /^(?!\d+\.\d+\.\d+\.\d+$)[a-z0-9][a-z0-9.-]*\.[a-z]{2,}$/i;

const iocClean     = String(ia.ioc).trim();
const isPublicIP   = _RE_IPV4.test(iocClean) && !_PRIVATE_RE.test(iocClean);
const isHash       = _RE_SHA256.test(iocClean) || _RE_SHA1.test(iocClean) || _RE_MD5.test(iocClean);
const isDomain     = _RE_DOMAIN.test(iocClean);
const iocBlockable = isPublicIP || isHash || isDomain;

let downgrade_applied = false;
if (ia.accion === 'bloquear' && !iocBlockable) {
  ia.accion   = 'analista';
  ia.gravedad = 'alta';
  ia.motivo   = 'DEGRADADO por guard: accion=bloquear requiere IOC actionable (IP pública, dominio o hash). Original: ' + ia.motivo.substring(0, 150);
  downgrade_applied = true;
}

// ─── 5. PULL DE CONTEXTO DEL CLASIFICADOR ─────────────────────────
const clasif = $('Clasificador1').item.json;
const inc    = clasif.incident       || {};
const rule   = inc.rule              || {};
const agent  = inc.agent             || {};
const d      = inc.data              || {};
const mitre  = rule.mitre            || {};
const tc     = clasif.threat_context || { techniques: [], ips: {}, cves: [], domains: {}, files: {} };

// ─── 6. HELPERS + ENRIQUECIMIENTO PARA ANALISTA ───────────────────
const arr = v => (Array.isArray(v) ? v.join(', ') : (v ?? 'N/A'));

// 6.1 Prioridad basada en nivel Wazuh
const prioridad = rule.level >= 14 ? 'CRITICA'
                : rule.level >= 12 ? 'ALTA'
                : rule.level >= 7  ? 'MEDIA'
                                   : 'BAJA';

// 6.2 Mitigaciones numeradas
const mitigaciones_txt = ia.mitigaciones.length
  ? ia.mitigaciones.map((m, i) => `${i + 1}. ${m}`).join('\n')
  : 'Sin mitigaciones específicas';

// 6.3 DETECCIÓN DEL TIPO DE IOC
const RE_IPV6 = /^[0-9a-f:]+$/i;
const RE_CVE  = /^CVE-\d{4}-\d{4,7}$/i;

let ioc_type = 'none';
let ioc_is_actionable = false;

if (iocClean && iocClean !== 'Ninguno' && iocClean !== 'N/A') {
  if (isPublicIP) {
    ioc_type = 'ip_public';
    ioc_is_actionable = true;
  } else if (_RE_IPV4.test(iocClean) && _PRIVATE_RE.test(iocClean)) {
    ioc_type = 'ip_private';
  } else if (RE_IPV6.test(iocClean) && iocClean.includes(':')) {
    ioc_type = 'ipv6';
    ioc_is_actionable = true;
  } else if (_RE_SHA256.test(iocClean)) ioc_type = 'hash_sha256';
  else if (_RE_SHA1.test(iocClean))     ioc_type = 'hash_sha1';
  else if (_RE_MD5.test(iocClean))      ioc_type = 'hash_md5';
  else if (RE_CVE.test(iocClean))       ioc_type = 'cve';
  else if (_RE_DOMAIN.test(iocClean))   ioc_type = 'domain';
  else                                  ioc_type = 'other';
}

// 6.4 OpenCTI: score agregado de TODOS los tipos de IOC
const allIndicators = [
  ...(tc.ips?.indicators     || []),
  ...(tc.domains?.indicators || []),
  ...(tc.files?.indicators   || [])
];
const cti_score = allIndicators.length
  ? Math.max(...allIndicators.map(i => i.score || 0), 0)
  : 0;

const cti_score_bar = cti_score >= 80 ? '🟥🟥🟥🟥🟥'
                    : cti_score >= 60 ? '🟥🟥🟥🟥⬜'
                    : cti_score >= 40 ? '🟧🟧🟧⬜⬜'
                    : cti_score >= 20 ? '🟨🟨⬜⬜⬜'
                    : cti_score > 0   ? '🟩⬜⬜⬜⬜'
                                      : '⬜⬜⬜⬜⬜';

const cti_counts = [
  (clasif.summary?.total_ip_indicators     || 0) > 0 ? `${clasif.summary.total_ip_indicators} IP` : null,
  (clasif.summary?.total_domain_indicators || 0) > 0 ? `${clasif.summary.total_domain_indicators} dom` : null,
  (clasif.summary?.total_hash_indicators   || 0) > 0 ? `${clasif.summary.total_hash_indicators} hash` : null,
  (clasif.summary?.total_cves              || 0) > 0 ? `${clasif.summary.total_cves} CVE` : null
].filter(Boolean).join(' · ') || 'sin indicators';

const opencti_txt = clasif.has_threats         ? `🔴 **Amenazas ACTIVAS:** ${(clasif.confirmed_threats || []).join(', ')} | Score ${cti_score}/100 ${cti_score_bar} | ${cti_counts}`
                  : clasif.has_revoked_threats ? `🟡 **Revocadas (histórico):** ${(clasif.revoked_threats || []).join(', ')} | Score ${cti_score}/100 ${cti_score_bar} | ${cti_counts}`
                                               : `✅ Sin amenazas registradas en OpenCTI | ${cti_counts}`;

// 6.5 MITRE ATT&CK — técnicas con URLs multi-item y soporte subtécnicas
const mitre_ids_raw = Array.isArray(mitre.id) ? mitre.id : [];

// Técnicas: enlaces individuales por cada ID (soporta T#### y T####.###)
const attack_techs = mitre_ids_raw.length
  ? mitre_ids_raw.map(id => `[${id}](https://attack.mitre.org/techniques/${id.replace('.', '/')}/)`).join(', ')
  : 'N/A';

// link_mitre: primer ID para templates simples
const link_mitre = mitre_ids_raw[0]
  ? `https://attack.mitre.org/techniques/${mitre_ids_raw[0].replace('.', '/')}/`
  : null;

// link_mitre_txt: todos los IDs en formato Markdown compacto
const link_mitre_txt = mitre_ids_raw.length
  ? mitre_ids_raw.map(id => `[${id}](https://attack.mitre.org/techniques/${id.replace('.', '/')}/)`).join(' · ')
  : 'N/A';

// 6.6 Multi-fuente IP y usuario
const srcip_final = d.srcip || d.aws?.source_ip_address || d.office365?.ClientIP || 'N/A';
const user_final  = d.srcuser || d.dstuser || d.office365?.UserId || d.aws?.userIdentity?.userName || 'N/A';
const geo         = inc.GeoLocation ? `${inc.GeoLocation.country_name || '?'} / ${inc.GeoLocation.city_name || '?'}` : 'N/A';
// 6.6b CONTEXTO FORENSE POR FAMILIA DE ALERTA
// Detecta qué tipo de alerta Wazuh es y extrae los campos específicos
// que el analista necesita ver para entender qué pasó en segundos.

const groups   = Array.isArray(rule.groups) ? rule.groups : [];
const groupStr = groups.join(' ').toLowerCase();
const decName  = (inc.decoder?.name || '').toLowerCase();
const hasGroup = (...gs) => gs.some(g => groupStr.includes(g));

// Helper para formatear líneas "Campo: valor" solo si el valor existe
const line = (label, value, wrap = '') => {
  if (value === undefined || value === null || value === '' || value === 'N/A') return null;
  const v = wrap === '`' ? `\`${value}\`` : String(value);
  return `• ${label}: ${v}`;
};

let context_label = 'Contexto';
let context_lines = [];

// ── FIM (syscheck) ──
if (hasGroup('syscheck', 'ossec') && inc.syscheck) {
  const sc = inc.syscheck;
  context_label = '📁 Cambio en sistema de archivos (FIM)';
  context_lines = [
    line('Ruta',    sc.path, '`'),
    line('Evento',  sc.event),                               // added|modified|deleted
    line('Atributos cambiados', arr(sc.changed_attributes)),
    line('Tamaño antes/después', sc.size_before && sc.size_after ? `${sc.size_before} → ${sc.size_after} bytes` : null),
    line('SHA256 antes',  sc.sha256_before, '`'),
    line('SHA256 después', sc.sha256_after,  '`'),
    line('MD5 después',   sc.md5_after,     '`'),
    line('Usuario',       sc.uname_after || sc.audit?.user?.name),
    line('Grupo',         sc.gname_after),
    line('Proceso que modificó', sc.audit?.process?.name, '`'),
    line('PID',           sc.audit?.process?.id),
    line('PPID',          sc.audit?.process?.ppid)
  ];
}

// ── Vulnerability-detector ──
else if (hasGroup('vulnerability', 'vulnerability-detector') && d.vulnerability) {
  const v = d.vulnerability;
  context_label = '🔓 Vulnerabilidad detectada';
  context_lines = [
    line('CVE',           v.cve, '`'),
    line('Severidad',     v.severity),
    line('CVSS v3',       v.cvss?.cvss3?.base_score),
    line('Paquete',       v.package?.name, '`'),
    line('Versión',       v.package?.version, '`'),
    line('Vector ataque', v.cvss?.cvss3?.vector?.attack_vector),
    line('Publicada',     v.published),
    line('CWE',           v.cwe_reference),
    line('Título',        v.title)
  ];
}

// ── VirusTotal ──
else if (hasGroup('virustotal') && d.virustotal) {
  const vt = d.virustotal;
  context_label = '🦠 Análisis VirusTotal';
  context_lines = [
    line('Veredicto',     vt.malicious === '1' || vt.found === '1' ? '🔴 MALICIOSO' : '✅ Limpio'),
    line('Detecciones',   vt.positives && vt.total ? `${vt.positives}/${vt.total}` : null),
    line('SHA1',          vt.sha1, '`'),
    line('Fichero origen', vt.source?.file, '`'),
    line('Scan date',     vt.scan_date),
    line('Permalink',     vt.permalink)
  ];
}

// ── Auditd / execve ──
else if ((hasGroup('audit', 'audit_command', 'system_audit') || decName.includes('auditd')) && d.audit) {
  const a = d.audit;
  context_label = '⚙️ Ejecución de comando (auditd)';
  const execArgs = [a.execve?.a0, a.execve?.a1, a.execve?.a2, a.execve?.a3].filter(Boolean).join(' ');
  context_lines = [
    line('Comando',    a.command || a.exe, '`'),
    line('Argumentos', execArgs, '`'),
    line('Ejecutable', a.exe, '`'),
    line('CWD',        a.cwd, '`'),
    line('TTY',        a.tty),
    line('Usuario',    a.acct || a.auid),
    line('UID/EUID',   a.uid && a.euid ? `${a.uid}/${a.euid}` : null),
    line('PID/PPID',   a.pid && a.ppid ? `${a.pid}/${a.ppid}` : null),
    line('Syscall',    a.syscall),
    line('Resultado',  a.res || a.success),
    line('Clave',      a.key)
  ];
}

// ── SCA (Security Configuration Assessment) ──
else if (hasGroup('sca') && d.sca) {
  const sca = d.sca;
  context_label = '📋 Control de configuración (SCA)';
  context_lines = [
    line('Policy',      sca.policy),
    line('Control',     sca.check?.title),
    line('Resultado',   sca.check?.result),
    line('Razón',       sca.check?.reason),
    line('Fichero',     sca.check?.file, '`'),
    line('Remediation', sca.check?.remediation ? sca.check.remediation.substring(0, 200) + '...' : null)
  ];
}

// ── AWS ──
else if ((hasGroup('aws', 'amazon', 'guardduty') || d.integration === 'aws') && d.aws) {
  const aw = d.aws;
  context_label = '☁️ Evento AWS';
  context_lines = [
    line('Account ID',  aw.accountId),
    line('Región',      aw.region),
    line('Source',      aw.source),
    line('IP origen',   aw.source_ip_address, '`'),
    line('Instancia',   aw.resource?.instanceDetails?.instanceId, '`'),
    line('IP pública',  aw.resource?.instanceDetails?.networkInterfaces?.publicIp, '`'),
    line('IP remota',   aw.service?.action?.networkConnectionAction?.remoteIpDetails?.ipAddressV4, '`'),
    line('Count',       aw.service?.count),
    line('First seen',  aw.service?.eventFirstSeen),
    line('Last seen',   aw.service?.eventLastSeen)
  ];
}

// ── Office 365 ──
else if ((hasGroup('office365', 'o365') || d.integration === 'office365') && d.office365) {
  const o = d.office365;
  context_label = '📧 Evento Office 365';
  context_lines = [
    line('Operación',   o.Operation, '`'),
    line('Usuario',     o.UserId),
    line('IP cliente',  o.ClientIP, '`'),
    line('Resultado',   o.ResultStatus),
    line('Actor',       o.Actor?.ID),
    line('Subscription', o.Subscription)
  ];
}

// ── Docker ──
else if (hasGroup('docker') && d.docker) {
  const dk = d.docker;
  context_label = '🐳 Evento Docker';
  context_lines = [
    line('Acción',      dk.Action, '`'),
    line('Tipo',        dk.Type),
    line('Contenedor',  dk.Actor?.Attributes?.name, '`'),
    line('Imagen',      dk.Actor?.Attributes?.image, '`')
  ];
}

// ── OSCAP ──
else if (hasGroup('oscap') && d.oscap) {
  const os = d.oscap;
  context_label = '🔍 Escaneo OSCAP';
  context_lines = [
    line('Profile',     os.scan?.profile?.title),
    line('Benchmark',   os.scan?.benchmark?.id),
    line('Check',       os.check?.title),
    line('Severidad',   os.check?.severity),
    line('Resultado',   os.check?.result),
    line('OVAL ID',     os.check?.oval?.id, '`')
  ];
}

// ── MS Graph (Defender) ──
else if (hasGroup('ms-graph', 'microsoft', 'defender') && d['ms-graph']) {
  const m = d['ms-graph'];
  context_label = '🛡️ Alerta MS Graph / Defender';
  context_lines = [
    line('Título',          m.title),
    line('Categoría',       m.category),
    line('Severidad',       m.severity),
    line('Detection source', m.detectionSource),
    line('Determinación',   m.determination),
    line('Clasificación',   m.classification),
    line('Técnicas MITRE',  arr(m.mitreTechniques)),
    line('Estado',          m.status),
    line('Actor',           m.actorDisplayName),
    line('Threat',          m.threatDisplayName),
    line('URL alerta',      m.alertWebUrl)
  ];
}

// ── GitHub ──
else if (hasGroup('github') && d.github) {
  const g = d.github;
  context_label = '🐙 Evento GitHub';
  context_lines = [
    line('Acción',      g.action, '`'),
    line('Actor',       g.actor),
    line('Organización', g.org),
    line('Repo',        g.repo, '`'),
    line('País actor',  g.actor_location?.country_code)
  ];
}

// ── GCP ──
else if ((hasGroup('gcp') || d.integration === 'gcp') && d.gcp) {
  const g = d.gcp;
  context_label = '☁️ Evento GCP';
  context_lines = [
    line('Proyecto',    g.resource?.labels?.project_id),
    line('Tipo recurso', g.resource?.type),
    line('Ubicación',   g.resource?.labels?.location),
    line('Severidad',   g.severity),
    line('Query DNS',   g.jsonPayload?.queryName, '`'),
    line('Response',    g.jsonPayload?.responseCode)
  ];
}

// ── Red genérica (firewall, IDS, web) ──
else if (hasGroup('firewall', 'ids', 'web', 'web_attack', 'attack', 'ddos', 'dos', 'recon') || d.srcip || d.dstip) {
  context_label = '🌐 Contexto de red';
  context_lines = [
    line('IP origen',   d.srcip, '`'),
    line('IP destino',  d.dstip, '`'),
    line('Puerto orig', d.srcport),
    line('Puerto dest', d.dstport),
    line('Protocolo',   d.protocol),
    line('URL',         d.url, '`'),
    line('Acción',      d.action),
    line('Status',      d.status)
  ];
}

// ── Fallback: intentamos sacar lo que haya en data.* ──
else {
  context_label = 'ℹ️ Datos del evento';
  context_lines = [
    line('Usuario origen', d.srcuser),
    line('Usuario destino', d.dstuser),
    line('IP origen', d.srcip, '`'),
    line('Comando', d.command, '`'),
    line('Fichero', d.file, '`'),
    line('URL', d.url, '`'),
    line('Protocolo', d.protocol),
    line('Status', d.status)
  ];
}

// Filtra nulls y compone el bloque final
const context_txt_lines = context_lines.filter(Boolean);
const context_txt = context_txt_lines.length
  ? `**${context_label}**\n${context_txt_lines.join('\n')}`
  : `**${context_label}**\nSin datos específicos disponibles`;

// 6.7 Criticidad del agente
const agent_name = (agent.name || '').toLowerCase();
const criticidad_agente = /prod|prd|production/.test(agent_name) ? '🔴 ALTA (producción)'
                        : /dev|test|stage/.test(agent_name)      ? '🟢 BAJA (desarrollo)'
                                                                 : '🟡 NORMAL';

// 6.8 Ventana temporal
const ts_evento = inc.timestamp ? new Date(inc.timestamp) : null;
const minutos_desde = ts_evento ? Math.round((new Date() - ts_evento) / 60000) : null;
const ventana_temporal = minutos_desde === null ? 'N/A'
                       : minutos_desde < 2      ? '🔴 AHORA (<2 min)'
                       : minutos_desde < 15     ? `🟠 Reciente (${minutos_desde} min)`
                       : minutos_desde < 60     ? `🟡 Hace ${minutos_desde} min`
                       : minutos_desde < 1440   ? `⚪ Hace ${Math.round(minutos_desde / 60)}h`
                                                : `⚪ Hace ${Math.round(minutos_desde / 1440)}d`;

// 6.9 Frecuencia
const freq_txt = rule.frequency && rule.frequency > 1
  ? `${rule.frequency} eventos correlacionados`
  : '1 evento';

// 6.10 Compliance tags pre-renderizados
const compliance = [];
if (rule.pci_dss?.length)     compliance.push(`**PCI-DSS** ${rule.pci_dss.join('/')}`);
if (rule.hipaa?.length)       compliance.push(`**HIPAA** ${rule.hipaa.join('/')}`);
if (rule.gdpr?.length)        compliance.push(`**GDPR** ${rule.gdpr.join('/')}`);
if (rule.nist_800_53?.length) compliance.push(`**NIST** ${rule.nist_800_53.join('/')}`);
const compliance_txt = compliance.length ? compliance.join(' | ') : 'Ninguno';

// 6.11 OPCIONES DE RESPUESTA adaptadas al tipo de IOC
function buildOpciones(iocType, ioc) {
  const op_escalar = `🚨 \`escalar\` → Notifica al canal Tier-2 para investigación profunda (sin modificar infraestructura)`;
  const op_cerrar  = `❌ \`cerrar\` → Marca como revisado sin acción. Queda registrado para auditoría`;

  let op_bloquear = null;
  switch (iocType) {
    case 'ip_public':
    case 'ipv6':
      op_bloquear = `🔨 \`bloquear\` → Añade **${ioc}** al alias \`Bloqueo_SOAR\` en OPNsense (reversible)`;
      break;
    case 'domain':
      op_bloquear = `🔨 \`bloquear\` → Bloqueo DNS del dominio **${ioc}** (pendiente integración Unbound)`;
      break;
    case 'hash_sha256':
    case 'hash_sha1':
    case 'hash_md5':
      op_bloquear = `🔨 \`bloquear\` → Cuarentena del fichero **${ioc.substring(0, 16)}...** (pendiente integración EDR)`;
      break;
    default:
      op_bloquear = null;
  }

  const opciones = [];
  if (op_bloquear) opciones.push(op_bloquear);
  opciones.push(op_escalar);
  if (iocType === 'cve') {
    opciones.push(`🩹 \`parchear\` → Abrir ticket de patch management (pendiente integración)`);
  }
  opciones.push(op_cerrar);
  return opciones;
}
const opciones_respuesta = buildOpciones(ioc_type, iocClean);
const opciones_txt = opciones_respuesta.map(o => `• ${o}`).join('\n');

// 6.12 DEEP-LINKS según tipo de IOC
// ⚠ Ajusta estas URLs a tu infraestructura real
const WAZUH_UI   = 'https://wazuh.ryoiki';
const OPENCTI_UI = 'http://opencti.ryoiki:8080';

// OpenCTI: search global (busca en observables, indicators, malware, etc.)
let link_opencti = OPENCTI_UI;
if (iocClean && iocClean !== 'Ninguno' && iocClean !== 'N/A') {
  link_opencti = `${OPENCTI_UI}/dashboard/search/knowledge/${encodeURIComponent(iocClean)}?sortBy=_score&orderAsc=false`;
}

// Wazuh: deep-link al Discover filtrado por id de la alerta.
// Los paréntesis van URL-encoded para que Discord renderice bien [txt](url).
const link_wazuh = inc.id
  ? `${WAZUH_UI}/app/data-explorer/discover#?_a=(discover:(columns:!(_source),isDirty:!f,sort:!()),metadata:(indexPattern:'wazuh-alerts-*',view:discover))&_g=(filters:!(),refreshInterval:(pause:!t,value:0),time:(from:now-48h,to:now))&_q=(filters:!(('$state':(store:appState),meta:(alias:!n,disabled:!f,index:'wazuh-alerts-*',key:id,negate:!f,params:(query:'${inc.id}'),type:phrase),query:(match_phrase:(id:'${inc.id}')))),query:(language:kuery,query:''))`.replace(/\(/g, '%28').replace(/\)/g, '%29')
  : WAZUH_UI;

// 6.13 PREVIEW de la acción automática adaptado al tipo IOC
let accion_preview = '';
if (ia.accion === 'bloquear') {
  switch (ioc_type) {
    case 'ip_public':
    case 'ipv6':
      accion_preview = `⚙️ **Acción automática:** añadir \`${iocClean}\` al alias \`Bloqueo_SOAR\` en OPNsense.`;
      break;
    case 'domain':
      accion_preview = `⚙️ **Acción automática prevista:** bloqueo DNS de \`${iocClean}\` (pendiente integración Unbound).`;
      break;
    case 'hash_sha256':
    case 'hash_sha1':
    case 'hash_md5':
      accion_preview = `⚙️ **Acción automática prevista:** cuarentena del fichero \`${iocClean.substring(0, 16)}...\` (pendiente integración EDR).`;
      break;
    default:
      accion_preview = `⚠️ **Bloqueo solicitado pero IOC no actionable automáticamente** (\`${iocClean}\`, tipo ${ioc_type}).`;
  }
} else if (ia.accion === 'escalar') {
  accion_preview = `⚙️ **Acción automática:** notificación crítica al canal Tier-2.`;
} else if (ia.accion === 'ignorar') {
  accion_preview = `⚙️ **Acción automática:** ninguna. Evento registrado para auditoría.`;
} else {
  accion_preview = `⚙️ **Intervención manual requerida.** El analista escoge opción abajo.`;
}

// ─── 7. OUTPUT — objeto plano listo para Discord/OPNsense ─────────
return [{
  json: {
    // — Decisión IA —
    resumen:            ia.resumen,
    gravedad:           ia.gravedad,
    accion:             ia.accion,
    motivo:             ia.motivo,
    ioc:                iocClean,
    ioc_type,
    ioc_is_actionable,
    mitigaciones:       ia.mitigaciones,
    mitigaciones_txt,
    _razonamiento:      ia._razonamiento,
    accion_preview,

    // — Incidente Wazuh —
    agente:             agent.name || 'N/A',
    agente_ip:          agent.ip   || 'N/A',
    criticidad_agente,
    nivel:              rule.level ?? 'N/A',
    prioridad,
    descripcion:        rule.description || 'N/A',
    grupos:             arr(rule.groups),
    regla_id:           rule.id || 'N/A',
    frecuencia:         rule.frequency ?? 1,
    freq_txt,
    srcip:              srcip_final,
    srcuser:            user_final,
    geo,
    ventana_temporal,
    timestamp_evento:   inc.timestamp || 'N/A',
    full_log:           (inc.full_log || 'N/A').substring(0, 500),
    mitre_ids:          arr(mitre.id),
    mitre_techs:        arr(mitre.technique),
    mitre_tacts:        arr(mitre.tactic),
    compliance_txt,
    context_txt,
    context_label,

    // — OpenCTI —
    has_threats:         clasif.has_threats || false,
    has_revoked_threats: clasif.has_revoked_threats || false,
    confirmed_threats:   (clasif.confirmed_threats || []).join(', ') || 'Ninguno',
    revoked_threats:     (clasif.revoked_threats || []).join(', ')   || 'Ninguno',
    opencti_txt,
    cti_score,
    cti_counts,
    attack_techs,

    // — Opciones + Links —
    opciones_txt,
    link_wazuh,
    link_opencti,
    link_mitre,               // string: primer ID
    link_mitre_txt,           // string: todos los IDs como Markdown links

    // — Meta / debug —
    parse_ok,
    downgrade_applied,
    raw_llm: rawText.substring(0, 300),

    // — Raw objects —
    incident:       inc,
    threat_context: tc
  }
}];

